use nepl3_core::{budget::{Budget,Limits},value::NdfValue};
fn main(){
 let value=NdfValue::List(vec![NdfValue::Unit;100_000]);
 for work in [1,400_000]{
  let mut b=Budget::new(Limits{work,allocation_units:10_000_000,depth:10,..Limits::default()});
  let r=value.equal_with_budget(&value,&mut b);
  println!("width100000 Work{work}: {r:?}; usage {:?}",b.usage());
 }
}

use nepl3_core::{budget::{Budget,Limits},value::NdfValue};
fn main(){
 let value=NdfValue::List(vec![NdfValue::Unit;100_000]);
 let mut b=Budget::new(Limits{work:500_000,allocation_units:10_000_000,depth:10,..Limits::default()});
 assert_eq!(value.equal_with_budget(&value,&mut b),Ok(true));
 println!("width100000 Work500000: true; usage {:?}",b.usage());
}

