  let request=RenameRequest{key:old.key(),source:input.reference(),offset:7,new_name:"cd".into(),writable:vec![root.reference()]};
  let mut b=budget();match prepare(&parsed,&old,&bound,&request,&mut b){Ok(mut draft)=>{let (a,c)=draft.with_operation(|sources,_,_|(sources.latest(&input.identity().source).unwrap().text().to_owned(),sources.latest(&root.identity().source).unwrap().text().to_owned()));assert_eq!(a,"lambda cd cd");assert_eq!(c,"cd");
let (changed,changed_root)=draft.with_operation(|sources,_,_|(sources.latest(&input.identity().source).unwrap().clone(),sources.latest(&root.identity().source).unwrap().clone()));
let mut new_maps=Vec::new();for start in [7,10]{if split{for offset in 0..2{new_maps.push(Mapping{source:changed_root.span(offset,offset+1).map_err(err)?,target:changed.span(start+offset,start+offset+1).map_err(err)?,kind:MappingKind::Exact});}}else{new_maps.push(Mapping{source:changed_root.span(0,2).map_err(err)?,target:changed.span(start,start+2).map_err(err)?,kind:MappingKind::Exact});}}
let next_parse=draft.with_operation(|_,b,a|parse_completed_with_aux(&changed,&[changed_root],&new_maps,profile,b,a))?;
let(next,next_bound)=draft.with_operation(|sources,b,a|->Result<_,String>{let mut c=FoundationCodec::new(profile.registry(),sources,a).map_err(err)?;let next=keyed::prepare("independent-rename",next_parse.tree(),BindingOptions,b.limits(),profile,&mut c,b).map_err(err)?;let bound=next.execute(b,a).map_err(err)?;Ok((next,bound))})?;
let result=draft.accept(&next_parse,&next,&next_bound);match result.outcome{RenameOutcome::Complete{edits,..}=>{assert_eq!(edits.len(),1);assert_eq!(edits[0].span.snapshot_ref().source,root.identity().source);assert_eq!(edits[0].replacement,"cd");},other=>return Err(format!("split={split} actual reparse accept: {other:?}"))};
println!("split={split} unique exact inverse: actual candidate parse/analyze/accept and single writable edit pass");},Err(e)=>return Err(format!("split={split}: {e:?}"))};Ok(())
 })?;}
 Ok(())
}

