fn parse_completed(source: &SourceSnapshot, resolved: &ResolvedParseProfile<'_>, b: &mut Budget, a: &mut SourceAdmission) -> Result<CompletedParse,String> {
    parse_completed_with_aux(source,&[],&[],resolved,b,a)
}
fn parse_completed_with_aux(source: &SourceSnapshot, extras: &[SourceSnapshot], maps: &[nepl3_core::origin::Mapping], resolved: &ResolvedParseProfile<'_>, b: &mut Budget, a: &mut SourceAdmission) -> Result<CompletedParse,String> {
    let r=resolved.registry();
    let p=resolved.language("B", b).map_err(err)?;
    let foundation=r.selected("nepl3.foundation",1).ok_or("foundation")?;
    let mut store = SourceStore::default();
    store.insert(source.clone()).map_err(err)?;
    for source in extras { store.insert(source.clone()).map_err(err)?; }
    let value = Environment {
        bindings: vec![],
        resources: vec![],
    };
    let digest = environment_digest(&value, foundation, r, b).map_err(err)?;
    let raw = ReaderContext {
        schema: p.schema.clone(),
        category: "Expr".into(),
        mode: "Code".into(),
        origins: extras.iter().map(|v|v.span(0,v.text().len() as u64).map(nepl3_core::origin::Origin::Direct)).collect::<Result<_,_>>().map_err(err)?,
        environment: EnvironmentEntry {
            id: 0,
            digest,
            value,
        },
    };
    let environments = {
        let mut codec = FoundationCodec::new(r, &store, a).map_err(err)?;
        let proof = raw.check(&mut codec, &store, r, b).map_err(err)?;
        ParseEnvironmentSet::prepare(
            resolved,
            &[EnvironmentInput {
                alias: "B",
                context: &proof,
            }],
            &store,
            &mut codec,
            b,
        )
        .map_err(err)?
    };
    let entry = resolved.entry("B", None, b).map_err(err)?;
    let states = [LanguageReaderState {
        alias: "B".into(),
        state: NdfValue::Unit,
    }];
    let mut parser =
        ParseSession::new("binding-parse".into(), resolved, &environments, b).map_err(err)?;
    let mut result = parser
        .read_completed(
            ParseRequest {
                snapshot: &source,
                start: 0,
                limit: source.text().len() as u64,
                final_input: true,
                entry: &entry,
                states: &states,
            },
            &store,
            b,
            a,
        )
        .map_err(err)?;
    let mut reservations = 0;
    let mut additional=false;
    loop {
        let progress=match result {
            ParseCompletion::Complete(parsed)=>{assert_eq!(parsed.cursor(),source.text().len() as u64);return Ok(parsed)},
            ParseCompletion::Progress(reply)=>reply,
        };
        match progress.outcome {
            ParseOutcome::Await { call, continuation } => {
                let ProviderCall::Read {
                    operation,
                    request,
                    depth_base,
                    ..
                } = call.as_ref()
                else {
                    return Err("unexpected provider".into());
                };
                let mut declared = SourceStore::default();
                for source in &request.sources {
                    declared.insert(source.clone()).map_err(err)?;
                }
                let snapshot = declared
                    .resolve(&request.snapshot)
                    .ok_or("request source")?;
                let mut terminal = b
                    .with_depth_at_least(*depth_base, |b| {
                        let mut codec = FoundationCodec::new(r, &declared, a)
                            .map_err(|_| nepl3_reader::runtime::ReaderError::Context)?;
                        let checked = request
                            .context
                            .check(&mut codec, &declared, r, b)
                            .map_err(|_| nepl3_reader::runtime::ReaderError::Context)?;
                        nepl3_reader::builtin::provider::read(
                            operation,
                            ReadRequest {
                                snapshot,
                                start: request.start,
                                limit: request.limit,
                                final_input: request.final_input,
                                context: &checked,
                                state: &request.state,
                            },
                            r,
                            &declared,
                            b,
                            a,
                        )
                    })
                    .map_err(err)?;
                if !additional && let nepl3_reader::model::ReadReply::Matched {sources,source_maps,..}=&mut terminal {
                    for source in extras {
                        if !sources.iter().any(|v|v.identity()==source.identity()) { sources.push(source.clone()); }
                    }
                    source_maps.extend_from_slice(maps);
                    additional=true;
                }
                result = parser
                    .resume_completed(
                        &continuation,
                        ProviderReply::Read(Box::new(terminal)),
                        &store,
                        b,
                        a,
                    )
                    .map_err(err)?;
            }
            ParseOutcome::Reserve { continuation, .. } => {
                reservations += 1;
                let reserved = SourceReservation {
                    source_id: SourceId(format!("decoded-{reservations}")),
                    revision: 0,
                    uri: format!("memory:decoded-{reservations}"),
                };
                result = parser
                    .reserve_completed(&continuation, &reserved, &store, b, a)
                    .map_err(err)?;
            }
            other => return Err(format!("candidate: {other:?}")),
        }
    }
}


