  for start in [7,8+len] {let points=if split{vec![0,name.chars().next().unwrap().len_utf8() as u64,len]}else{vec![0,len]};for pair in points.windows(2){maps.push(Mapping{source:origin.span(pair[0],pair[1]).map_err(err)?,target:input.span(start+pair[0],start+pair[1]).map_err(err)?,kind:MappingKind::Exact});}}
  let parsed=parse_completed_with_aux(input,&[origin.clone()],&maps,profile,&mut budget(),&mut SourceAdmission::default())?;
  let empty=SourceStore::default();let mut a=SourceAdmission::default();let mut c=FoundationCodec::new(profile.registry(),&empty,&mut a).map_err(err)?;
  let old=keyed::prepare("independent-rename",parsed.tree(),BindingOptions,budget().limits(),profile,&mut c,&mut budget()).map_err(err)?;let bound=old.execute(&mut budget(),&mut SourceAdmission::default()).map_err(err)?;
  let request=RenameRequest{key:old.key(),source:input.reference(),offset:7,new_name:new_name.into(),writable:vec![origin.reference()]};let mut b=budget();let mut draft=prepare(&parsed,&old,&bound,&request,&mut b).map_err(err)?;
  let (changed,changed_origin)=draft.with_operation(|sources,_,_|(sources.latest(&input.identity().source).unwrap().clone(),sources.latest(&origin.identity().source).unwrap().clone()));assert_eq!(changed.text(),want);assert_eq!(changed_origin.text(),new_name);
  // New source geometry comes from this actual reader reply, not old segment boundaries.
  // Alternate whole/split representation and retain UTF-8 scalar boundaries.
  let points=if !split && new_name.chars().count()>1{vec![0,new_name.chars().next().unwrap().len_utf8() as u64,new_len]}else{vec![0,new_len]};
  let mut new_maps=Vec::new();for start in [7,8+new_len]{for pair in points.windows(2){new_maps.push(Mapping{source:changed_origin.span(pair[0],pair[1]).map_err(err)?,target:changed.span(start+pair[0],start+pair[1]).map_err(err)?,kind:MappingKind::Exact});}}new_maps.reverse();
  let next_parse=draft.with_operation(|_,b,a|parse_completed_with_aux(&changed,&[changed_origin],&new_maps,profile,b,a))?;
  let(next,next_bound)=draft.with_operation(|sources,b,a|->Result<_,String>{let mut c=FoundationCodec::new(profile.registry(),sources,a).map_err(err)?;let next=keyed::prepare("independent-rename",next_parse.tree(),BindingOptions,b.limits(),profile,&mut c,b).map_err(err)?;let bound=next.execute(b,a).map_err(err)?;Ok((next,bound))})?;
  let result=draft.accept(&next_parse,&next,&next_bound);match result.outcome{RenameOutcome::Complete{edits,..}=>{assert_eq!(edits.len(),1);assert_eq!((edits[0].span.start(),edits[0].span.end()),(0,len));assert_eq!(edits[0].span.snapshot_ref().source,origin.identity().source);assert_eq!(edits[0].replacement,new_name);assert_eq!(edits[0].expected_digest,Digest::of(name.as_bytes()));},other=>return Err(format!("{name}->{new_name} split={split}: {other:?}"))};
  println!("{name}->{new_name} split={split}: actual new segmentation/UTF-8 geometry and one original-revision edit pass");Ok(())
 })?;}}
