fn parse_completed(
    source: &SourceSnapshot,
    resolved: &ResolvedParseProfile<'_>,
    b: &mut Budget,
    a: &mut SourceAdmission,
) -> Result<CompletedParse, String> {
    parse_completed_with_aux(source, &[], &[], resolved, b, a)
}
fn parse_completed_with_aux(
    source: &SourceSnapshot,
    extras: &[SourceSnapshot],
    maps: &[nepl3_core::origin::Mapping],
    resolved: &ResolvedParseProfile<'_>,
    b: &mut Budget,
    a: &mut SourceAdmission,
) -> Result<CompletedParse, String> {
    let r = resolved.registry();
    let p = resolved.language("B", b).map_err(err)?;
    let foundation = r.selected("nepl3.foundation", 1).ok_or("foundation")?;
    let mut store = SourceStore::default();
    store.insert(source.clone()).map_err(err)?;
    for source in extras {
        store.insert(source.clone()).map_err(err)?;
    }
    let value = Environment {
        bindings: vec![],
        resources: vec![],
    };
    let digest = environment_digest(&value, foundation, r, b).map_err(err)?;
    let raw = ReaderContext {
        schema: p.schema.clone(),
        category: "Expr".into(),
        mode: "Code".into(),
        origins: extras
            .iter()
            .map(|v| {
                v.span(0, v.text().len() as u64)
                    .map(nepl3_core::origin::Origin::Direct)
            })
            .collect::<Result<_, _>>()
            .map_err(err)?,
        environment: EnvironmentEntry {
            id: 0,
            digest,
            value,
        },
    };
    let mut raws = vec![raw];
    for language in &resolved.profile().languages {
        if language.alias == "B" {
            continue;
        }
        let p = resolved.language(&language.alias, b).map_err(err)?;
        let mut raw = raws[0].clone();
        raw.schema = p.schema.clone();
        raw.category = language.default_category.clone();
        raws.push(raw);
    }
    let environments = {
        let mut codec = FoundationCodec::new(r, &store, a).map_err(err)?;
        let proofs = raws
            .iter()
            .map(|raw| raw.check(&mut codec, &store, r, b).map_err(err))
            .collect::<Result<Vec<_>, _>>()?;
        let inputs = resolved
            .profile()
            .languages
            .iter()
            .zip(&proofs)
            .map(|(language, proof)| EnvironmentInput {
                alias: &language.alias,
                context: proof,
            })
            .collect::<Vec<_>>();
        ParseEnvironmentSet::prepare(resolved, &inputs, &store, &mut codec, b).map_err(err)?
    };
    let entry = resolved.entry("B", None, b).map_err(err)?;
    let states = resolved
        .profile()
        .languages
        .iter()
        .map(|v| LanguageReaderState {
            alias: v.alias.clone(),
            state: NdfValue::Unit,
        })
        .collect::<Vec<_>>();
    let mut parser =
        ParseSession::new("binding-parse".into(), resolved, &environments, b).map_err(err)?;
    let mut result = parser
        .read_completed(
            ParseRequest {
                snapshot: source,
                start: 0,
                limit: source.text().len() as u64,
                final_input: true,
                entry: &entry,
                states: &states,
            },
            &store,
            b,
            a,
        )
        .map_err(err)?;
    let mut reservations = 0;
    let mut additional = false;
    loop {
        let progress = match result {
            ParseCompletion::Continue(parsed) => {
                assert_eq!(parsed.cursor(), source.text().len() as u64);
                return Ok(parsed);
            }
            ParseCompletion::Break(reply) => reply,
        };
        match progress.outcome {
            ParseOutcome::Await { call, continuation } => {
                let ProviderCall::Read {
                    operation,
                    request,
                    depth_base,
                    ..
                } = call.as_ref()
                else {
                    return Err("unexpected provider".into());
                };
                let mut declared = SourceStore::default();
                for source in &request.sources {
                    declared.insert(source.clone()).map_err(err)?;
                }
                let snapshot = declared
                    .resolve(&request.snapshot)
                    .ok_or("request source")?;
                let mut terminal = b
                    .with_depth_at_least(*depth_base, |b| {
                        let mut codec = FoundationCodec::new(r, &declared, a)
                            .map_err(|_| nepl3_reader::runtime::ReaderError::Context)?;
                        let checked = request
                            .context
                            .check(&mut codec, &declared, r, b)
                            .map_err(|_| nepl3_reader::runtime::ReaderError::Context)?;
                        nepl3_reader::builtin::provider::read(
                            operation,
                            ReadRequest {
                                snapshot,
                                start: request.start,
                                limit: request.limit,
                                final_input: request.final_input,
                                context: &checked,
                                state: &request.state,
                            },
                            r,
                            &declared,
                            b,
                            a,
                        )
                    })
                    .map_err(err)?;
                if !additional
                    && let nepl3_reader::model::ReadReply::Matched {
                        sources,
                        source_maps,
                        ..
                    } = &mut terminal
                {
                    for source in extras {
                        if !sources.iter().any(|v| v.identity() == source.identity()) {
                            sources.push(source.clone());
                        }
                    }
                    source_maps.extend_from_slice(maps);
                    additional = true;
                }
                result = parser
                    .resume_completed(
                        &continuation,
                        ProviderReply::Read(Box::new(terminal)),
                        &store,
                        b,
                        a,
                    )
                    .map_err(err)?;
            }
            ParseOutcome::Reserve { continuation, .. } => {
                reservations += 1;
                let reserved = SourceReservation {
                    source_id: SourceId(format!("decoded-{reservations}")),
                    revision: 0,
                    uri: format!("memory:decoded-{reservations}"),
                };
                result = parser
                    .reserve_completed(&continuation, &reserved, &store, b, a)
                    .map_err(err)?;
            }
            other => return Err(format!("candidate: {other:?}")),
        }
    }
}


use nepl3_engine::{analysis::{BindingOptions,rename::*},portable::analysis as keyed};
fn main()->Result<(),String>{
 let doc=load("conformance/fixtures/grammar/binding/execution.neplg")?;let compiled=nepl3_tools::bootstrap::catalog::compile(&doc,"review.rename",&mut budget(),&mut SourceAdmission::default())?;
 let doc=load("examples/grammar/binding.neplg")?;let mut other=nepl3_tools::bootstrap::catalog::compile(&doc,"review.rename-other",&mut budget(),&mut SourceAdmission::default())?;
 other.package.forms.first_mut().ok_or("form")?.spelling="otherReserved".into();
 let mut compiled=compiled;let schema=other.package.schema.clone();let descriptor=other.registry.descriptor(&schema).ok_or("descriptor")?.clone();compiled.registry.register(schema,descriptor,&mut budget()).map_err(err)?;compiled.registry.finalize(&mut budget()).map_err(err)?;
 for new_name in ["let","otherReserved"]{with_completed_input_extra(&compiled,Some(&other.package),"lambda x 1",|parsed,profile,_,_|{
  let empty=SourceStore::default();let mut a=SourceAdmission::default();let mut c=FoundationCodec::new(profile.registry(),&empty,&mut a).map_err(err)?;
  let old=keyed::prepare("independent-rename",parsed.tree(),BindingOptions,budget().limits(),profile,&mut c,&mut budget()).map_err(err)?;let bound=old.execute(&mut budget(),&mut SourceAdmission::default()).map_err(err)?;
  let input=parsed.tree().bundle.sources.iter().find(|s|s.text()=="lambda x 1").ok_or("input")?;
  let request=RenameRequest{key:old.key(),source:input.reference(),offset:7,new_name:new_name.into(),writable:vec![input.reference()]};
  let separately_parsed=parse_completed(input,profile,&mut budget(),&mut SourceAdmission::default())?;
  assert_eq!(separately_parsed.tree(),parsed.tree());
  assert!(matches!(prepare(&separately_parsed,&old,&bound,&request,&mut budget()),Err(RenameError::RequestMismatch)));
  let copied=parsed.tree().clone();let copied_prepared=keyed::prepare("independent-rename",&copied,BindingOptions,budget().limits(),profile,&mut c,&mut budget()).map_err(err)?;let copied_bound=copied_prepared.execute(&mut budget(),&mut SourceAdmission::default()).map_err(err)?;
  assert!(matches!(prepare(parsed,&copied_prepared,&copied_bound,&request,&mut budget()),Err(RenameError::RequestMismatch)));
  let mut operation=budget();let prepared=prepare(parsed,&old,&bound,&request,&mut operation);
  if new_name=="let"{assert!(matches!(prepared,Err(RenameError::InvalidName)));println!("unused definition cannot rename to own reserved head; seal swapping rejected");return Ok(())}
  let mut draft=prepared.map_err(err)?;
  let next_parse=draft.with_operation(|sources,b,a|parse_completed(sources.latest(&input.identity().source).ok_or("candidate")?,profile,b,a))?;
  let(next,bound)=draft.with_operation(|sources,b,a|->Result<_,String>{let mut c=FoundationCodec::new(profile.registry(),sources,a).map_err(err)?;let next=keyed::prepare("independent-rename",next_parse.tree(),BindingOptions,b.limits(),profile,&mut c,b).map_err(err)?;let bound=next.execute(b,a).map_err(err)?;Ok((next,bound))})?;
  let reply=draft.accept(&next_parse,&next,&bound);assert!(matches!(reply.outcome,RenameOutcome::Complete{..}));println!("head reserved only in another selected language remains valid here");Ok(())
 })?;}Ok(())
}

